<?php
namespace Modules\Academy\Services;
use Core\database\DB;use RuntimeException;
class OfflineInstallmentPaymentService{
 public function record(int$a,int$invoiceId,int$installmentId,array$d):array{$this->ensureColumns();$method=(string)($d['method']??'');if(!in_array($method,['card_to_card','pos'],true))throw new RuntimeException('روش پرداخت معتبر نیست.');$reference=trim((string)($d['reference']??''));if($reference==='')throw new RuntimeException('شماره پیگیری پرداخت الزامی است.');$payerName=trim((string)($d['payerName']??''));if(mb_strlen($payerName)<2||mb_strlen($payerName)>190)throw new RuntimeException('نام شخص پرداخت‌کننده الزامی است.');$bankCardType=trim((string)($d['bankCardType']??''));if(!in_array($bankCardType,['melli','sepah','mellat','tejarat','saderat','refah','keshavarzi','maskan','post','tosee_saderat','sanat_madan','eghtesad_novin','parsian','pasargad','saman','sarmayeh','sina','shahr','ayandeh','gardeshgari','iran_zamin','resalat','melal','karafarin','dey','middle_east','other'],true))throw new RuntimeException('نوع کارت بانکی معتبر نیست.');$paymentDate=(string)($d['paymentDate']??'');$paymentTime=(string)($d['paymentTime']??'');$paidAt=\DateTime::createFromFormat('!Y-m-d H:i',$paymentDate.' '.$paymentTime);if(!$paidAt||$paidAt->format('Y-m-d H:i')!==$paymentDate.' '.$paymentTime)throw new RuntimeException('روز و ساعت پرداخت معتبر نیست.');if($paidAt->getTimestamp()>time()+300)throw new RuntimeException('زمان پرداخت نمی‌تواند در آینده باشد.');$paidAt=$paidAt->format('Y-m-d H:i:s');$description=trim((string)($d['description']??''));$service=new AcademyTermService();$allowed=array_column($service->invoiceBootstrap($a)['invoices']??[],'id');if(!in_array($invoiceId,$allowed,true))throw new RuntimeException('دسترسی به این فاکتور ندارید.');$invoice=DB::table('academy_branch_course_term_invoices')->where('term_invoice_id',$invoiceId)->whereNull('deleted_at')->first();$installment=DB::table('academy_branch_course_term_invoice_installments')->where('term_invoice_installment_id',$installmentId)->where('invoice_id',$invoiceId)->whereNull('deleted_at')->first();if(!$invoice||!$installment)throw new RuntimeException('فاکتور یا قسط یافت نشد.');if($installment['status']==='paid')throw new RuntimeException('این قسط قبلاً پرداخت شده است.');$first=DB::table('academy_branch_course_term_invoice_installments')->where('invoice_id',$invoiceId)->whereNull('deleted_at')->where('status','<>','paid')->orderBy('installment_number')->orderBy('term_invoice_installment_id')->first();if(!$first||(int)$first['term_invoice_installment_id']!==$installmentId)throw new RuntimeException('ابتدا قسط قبلی را ثبت کنید.');$now=date('Y-m-d H:i:s');transaction(function()use($a,$invoiceId,$installmentId,$installment,$method,$reference,$payerName,$bankCardType,$paidAt,$description,$now){DB::table('academy_term_invoice_payments')->insert(['invoice_id'=>$invoiceId,'installment_id'=>$installmentId,'user_id'=>$a,'gateway'=>'offline','payment_method'=>$method,'payer_name'=>$payerName,'bank_card_type'=>$bankCardType,'amount'=>(int)round((float)$installment['amount']),'currency'=>strtoupper((string)env('ZARINPAL_CURRENCY','IRT'))==='IRR'?'IRR':'IRT','callback_token'=>bin2hex(random_bytes(32)),'reference_id'=>$reference,'status'=>'paid','gateway_message'=>'پرداخت خارج از درگاه ثبت شد.','description'=>$description?:null,'verified_at'=>$paidAt,'created_at'=>$now,'created_by'=>$a,'updated_at'=>$now,'updated_by'=>$a]);DB::table('academy_branch_course_term_invoice_installments')->where('term_invoice_installment_id',$installmentId)->update(['status'=>'paid','paid_at'=>$paidAt,'approved_at'=>$now,'approved_by'=>$a,'updated_at'=>$now,'updated_by'=>$a]);$remaining=DB::table('academy_branch_course_term_invoice_installments')->where('invoice_id',$invoiceId)->whereNull('deleted_at')->where('status','<>','paid')->count();$paid=DB::table('academy_branch_course_term_invoice_installments')->where('invoice_id',$invoiceId)->whereNull('deleted_at')->where('status','paid')->count();DB::table('academy_branch_course_term_invoices')->where('term_invoice_id',$invoiceId)->update(['status'=>$remaining===0?'paid':($paid>0?'partial':'issued'),'updated_at'=>$now,'updated_by'=>$a]);});return['referenceId'=>$reference,'method'=>$method,'paidAt'=>$paidAt,'payerName'=>$payerName,'bankCardType'=>$bankCardType];}
 private function ensureColumns():void{foreach(['payer_name'=>'VARCHAR(190) NULL AFTER payment_method','bank_card_type'=>'VARCHAR(40) NULL AFTER payer_name']as$column=>$definition){$q=db()->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='academy_term_invoice_payments' AND COLUMN_NAME=?");$q->execute([$column]);if(!(int)$q->fetchColumn())db()->exec("ALTER TABLE academy_term_invoice_payments ADD COLUMN `$column` $definition");}}
}
